#include "qt_waveform_overlay.hpp"
#include "live_capture_wave.hpp"
#include "qt_metrics.hpp"
#include <QApplication>
#include <QElapsedTimer>
#include <QTimer>
#include <QVBoxLayout>
#include <iostream>
#include <stdexcept>
using namespace pitatuner;
std::shared_ptr<const waveform::Frame> signalFrame(uint64_t end,double pre=.02,double post=.2,int postPhase=0){
 auto f=std::make_shared<waveform::Frame>();const auto begin=end-2000000000ULL;f->axis={begin,end,2000};
 for(size_t tap=0;tap<2;tap++){waveform::Series series{};series.kind=tap?waveform::Kind::PostMeasured:waveform::Kind::PreMeasured;series.bins.reserve(2000);for(size_t i=0;i<2000;i++){const auto value=std::sin(double(i+(tap?postPhase:0))*.0314)*std::sin(double(i+(tap?postPhase:0))*.0071);const auto amp=tap?post:pre;waveform::Bin b{};b.begin_ns=begin+i*1000000;b.end_ns=b.begin_ns+1000000;b.finite=48;b.minimum=float((value-.12)*amp);b.maximum=float((value+.12)*amp);series.bins.push_back(b);}f->series.push_back(std::move(series));}return f;
}
int main(int argc,char** argv){QApplication app(argc,argv);unsigned checks=0;auto check=[&](bool b){++checks;if(!b)throw std::runtime_error("overlay display check="+std::to_string(checks));};try{
 displayonly::Gain quiet;for(uint64_t i=1;i<=600;i++)check(quiet.update(1e-8,i*16666667ULL)==1);
 displayonly::Gain capped;for(uint64_t i=1;i<=600;i++)check(capped.update(.0002,i*16666667ULL)<=64);check(capped.value()>63);
 displayonly::Gain gain;double last=1;for(uint64_t i=1;i<=120;i++){const auto g=gain.update(.02,i*16666667ULL);check(g>=last&&g<=40);last=g;}check(std::abs(gain.value()-40)<1);const auto oldGain=gain.value();check(gain.update(.02,2000000040ULL)<oldGain*1.01);gain.reset();check(gain.value()==1);
 // Every sample contributes, including impulses which step-32 point sampling loses.
 capture::livewave::Window envelope(120,2000);std::array<float,480> raw{};raw[17]=-.75f;raw[19]=.9f;envelope.add(0,3000000000,raw.data(),480,48000);envelope.add(1,3000000000,raw.data(),480,48000);check(envelope.ready(48000));const auto frame=envelope.publish(48000);const auto col=qt::overlay::columns(frame.series[0],frame.axis,360);float lo=0,hi=0;for(auto& c:col)if(c.valid){lo=std::min(lo,c.lo);hi=std::max(hi,c.hi);}check(lo==-.75f&&hi==.9f);check(!envelope.ready(48000));
 QWidget root;auto* layout=new QVBoxLayout(&root);auto* plot=new QCustomPlot(&root);plot->setMinimumHeight(300);qt::waveb::style(plot,"PRE / POST");auto* legend=new QLabel(&root);layout->addWidget(plot);layout->addWidget(legend);root.resize(800,380);root.show();app.processEvents();qt::overlay::Renderer renderer(plot,legend,"PRE","POST");pita::Key key{"synthetic-overlay",1,1};auto first=signalFrame(5000000000);const auto immutable=first->series[0].bins[100].minimum;qt::waveb::axes(plot,plot,first->axis);check(renderer.update(first,key,1000000000));auto* preCurve=renderer.curve(0);auto* postCurve=renderer.curve(1);check(plot->plottableCount()==2&&preCurve&&postCurve);check(!renderer.update(first,key,1010000000)&&renderer.updates()==1);check(first->series[0].bins[100].minimum==immutable);check(preCurve->pen().color().alpha()==180&&postCurve->pen().color().alpha()==180);
 // Exercise actual queued Qt replots for 3 s, reporting call/render costs. This
 // is the owned synthetic renderer, not the user's OBS or a physical screen FPS.
 uint64_t renders=0,totalNs=0,maxNs=0,beginNs=0;QElapsedTimer clock;clock.start();QObject::connect(plot,&QCustomPlot::beforeReplot,&root,[&]{beginNs=clock.nsecsElapsed();});QObject::connect(plot,&QCustomPlot::afterReplot,&root,[&]{const auto elapsed=uint64_t(clock.nsecsElapsed())-beginNs;++renders;totalNs+=elapsed;maxNs=std::max(maxNs,elapsed);});
 QTimer ticker;ticker.setTimerType(Qt::PreciseTimer);unsigned ticks=0;uint64_t maxUpdateNs=0;QObject::connect(&ticker,&QTimer::timeout,&root,[&]{const auto start=uint64_t(clock.nsecsElapsed());auto next=signalFrame(5000000000ULL+uint64_t(ticks+1)*16000000ULL);qt::waveb::axes(plot,plot,next->axis);renderer.update(next,key,1000000000ULL+uint64_t(ticks+1)*16000000ULL);plot->replot(QCustomPlot::rpQueuedReplot);maxUpdateNs=std::max(maxUpdateNs,uint64_t(clock.nsecsElapsed())-start);if(++ticks==180){ticker.stop();app.quit();}});ticker.start(16);app.exec();app.processEvents();check(ticks==180&&renders>150);check(renderer.curve(0)==preCurve&&renderer.curve(1)==postCurve&&plot->plottableCount()==2);check(std::abs(renderer.gain(0)/renderer.gain(1)-10)<.1);check(legend->text().contains("×")&&legend->text().contains("PRE")&&legend->text().contains("POST"));
 plot->replot(QCustomPlot::rpImmediateRefresh);check(plot->grab().save("overlay-comparison.png"));check(root.grab().save("overlay-matched-with-scales.png"));
 // Equal-time normalized envelopes overlap cyan through paint composition.
 const auto image=plot->grab().toImage();unsigned cyan=0;for(int y=0;y<image.height();y++)for(int x=0;x<image.width();x++){const auto c=image.pixelColor(x,y);if(c.red()<100&&c.green()>200&&c.blue()>200)++cyan;}check(cyan>30);auto different=signalFrame(7880000000,.02,.2,120);renderer.update(different,key,4000000000);plot->replot(QCustomPlot::rpImmediateRefresh);check(root.grab().save("overlay-with-scales.png"));const auto separated=plot->grab().toImage();unsigned green=0,blue=0;for(int y=0;y<separated.height();y++)for(int x=0;x<separated.width();x++){const auto c=separated.pixelColor(x,y);if(c.red()<100&&c.green()>130&&c.green()>c.blue()*1.2)++green;if(c.red()<100&&c.blue()>130&&c.blue()>c.green()*1.2)++blue;}check(green>30&&blue>30);
 // Exercise the actual buffered QWidget path under dark and light palettes.
 // QCP toPixmap bypasses its layer buffers and is not the product draw path.
 for(bool light:{false,true}){QPalette palette=plot->palette();palette.setColor(QPalette::Window,light?QColor(245,245,245):QColor(35,38,43));palette.setColor(QPalette::WindowText,light?QColor(20,20,20):QColor(235,235,235));plot->setPalette(palette);legend->setPalette(palette);app.processEvents();check(legend->text().contains(light?"#006e28":"#00dc50"));check(plot->axisRect()->backgroundBrush().color()==palette.color(QPalette::Window));check(plot->xAxis->tickLabelColor()==palette.color(QPalette::WindowText)&&plot->yAxis->labelColor()==palette.color(QPalette::WindowText));
  for(bool overlap:{false,true}){auto themed=signalFrame(9000000000,.02,.2,overlap?0:120);for(unsigned i=0;i<120;++i){renderer.update(themed,key,6000000000ULL+i*16000000ULL);themed=signalFrame(9000000000ULL+i*16000000ULL,.02,.2,overlap?0:120);}plot->replot(QCustomPlot::rpImmediateRefresh);const auto pixels=plot->grab().toImage();unsigned g=0,b=0,c=0;for(int y=0;y<pixels.height();++y)for(int x=0;x<pixels.width();++x){const auto color=pixels.pixelColor(x,y);if(color.green()>color.red()+50&&color.green()>color.blue()+25)++g;if(color.blue()>color.red()+50&&color.blue()>color.green()+25)++b;if(color.green()>color.red()+80&&color.blue()>color.red()+80)++c;}if(overlap)check(c>30);else check(g>30&&b>30);check(renderer.curve(0)==preCurve&&renderer.curve(1)==postCurve);}
 }
 renderer.clear();{auto palette=legend->palette();palette.setColor(QPalette::Window,QColor(35,38,43));legend->setPalette(palette);app.processEvents();check(legend->isHidden()&&legend->text().contains("#00dc50"));}check(plot->plottableCount()==2&&preCurve->data()->isEmpty()&&postCurve->data()->isEmpty());check(renderer.gain(0)==1&&renderer.gain(1)==1);check(renderer.update(first,{"new-source",2,1},5000000000));check(renderer.curve(0)==preCurve&&renderer.curve(1)==postCurve);
 std::cout<<"PASS "<<checks<<" display-only gain/quiet-cap/extrema/persistent-curve/queued-render/no-input-mutation checks; synthetic Qt ticks="<<ticks<<" renders="<<renders<<" avg_render_ms="<<(renders?double(totalNs)/renders/1e6:0)<<" max_render_ms="<<double(maxNs)/1e6<<" max_update_ms="<<double(maxUpdateNs)/1e6<<" cyan_pixels="<<cyan<<"; OBS/screen QA not run\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
